<script setup lang="ts">
import SingleFileUpload from '@/components/SingleFileUpload.vue'
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {launchApi,stages,defaults,rows,stateNames,actionNames,attachmentList,uploadAttachment,downloadAttachment,type Workspace,type Document,type Row,type Value,type LaunchAttachment} from '@/api/launch'
import {developmentWorkbenchApi} from '@/api/developmentWorkbench'
import {domainApi,type ProductDetailDto} from '@/api/domain'
import {developmentTabs,stageGuides,developmentActionLabel,changedKeys,overdue,developmentIssueTab} from '@/utils/developmentPresentation'
import {session} from '@/state/session'
import {confirmAction} from '@/state/uiConfirmation'
import {riskLabels,safeLink,formatDate} from '@/utils/candidatePresentation'
import {sections,riskNames,type Field,type Section} from './schema'
import CandidateFields from './CandidateFields.vue'
import AccessDialog from '@/components/AccessDialog.vue'
import ListPagination from '@/components/ListPagination.vue'
import SuccessToast from '@/components/SuccessToast.vue'
const props=defineProps<{projectId:string}>(),emit=defineEmits<{close:[];changed:[]}>(),api=launchApi(true)
const snapshot=ref<Document>()
const dialog=ref<HTMLDialogElement>(),workspace=ref<Workspace>(),loading=ref(true),busy=ref(false),error=ref(''),notice=ref(''),tab=ref('overview'),legacy=ref<Record<string,unknown>>({})
const doc=computed(()=>defaults({platform:workspace.value?.document.asin?'Amazon':'',...workspace.value?.document})),writer=computed(()=>session.canAccess(['development.write'])),reviewer=computed(()=>session.canAccess(['development.review'])),editable=computed(()=>writer.value&&['DRAFT','ACTIVE'].includes(workspace.value?.state??'')&&!Object.keys(workspace.value?.proposal??{}).length)
const editor=ref<{title:string;fields:Field[];key?:string|undefined;id?:Value|undefined;remove?:boolean}>(),draft=ref<Row>({}),initial=ref(''),editError=ref(''),action=ref(''),reason=ref(''),selfConfirmed=ref(false)
const changeReason=ref(''),readiness=ref<{action:string;issues:string[];version:number}>(),readinessError=ref(''),attachments=ref<LaunchAttachment[]>([]),historyPage=ref(1),historySize=ref(10)
const productOpen=ref(false),productQuery=ref(''),products=ref<ProductDetailDto[]>([]),productLoading=ref(false),productError=ref(''),selectedProduct=ref<ProductDetailDto>(),selectedSkus=ref<string[]>([]),productInitial=ref('')
const productDirty=computed(()=>productOpen.value&&JSON.stringify([selectedProduct.value?.id,selectedSkus.value])!==productInitial.value)
const dirty=computed(()=>(!!editor.value&&(JSON.stringify(draft.value)!==initial.value||!!changeReason.value))||productDirty.value)
let previous:HTMLElement|null=null,alive=true,readRequest=0
const history=computed(()=>[...(workspace.value?.history??[])].sort((a,b)=>b.version-a.version)),historyRows=computed(()=>history.value.slice((historyPage.value-1)*historySize.value,historyPage.value*historySize.value))
const currentSections=computed(()=>(developmentTabs.find(t=>t.key===tab.value)?.sections??[]).flatMap(key=>sections.filter(s=>s.key===key)))
const sourceCandidate=computed(()=>String(doc.value.sourceCandidateId??(legacy.value.item as {source?:{candidateId?:string}}|undefined)?.source?.candidateId??''))
const actions=computed(()=>{const w=workspace.value;if(!w||!writer.value)return [];const s=w.state,result:string[]=[];
 if(s==='DRAFT')result.push(Object.keys(w.baseline).length?'START':'SUBMIT','PAUSE');
 if(s==='ACTIVE'){if(!Object.keys(w.proposal).length)result.push(w.stage<4?'NEXT':'SUBMIT',...(w.stage>0?['BACK']:[]));result.push('PAUSE')}
 if(s==='PAUSED')result.push('RESUME');
 if(['PROJECT_REVIEW','FINAL_REVIEW'].includes(s)){if(reviewer.value)result.push(s==='FINAL_REVIEW'?'COMPLETE':'APPROVE','RETURN');result.push('WITHDRAW')}
 if(reviewer.value&&!['COMPLETED','VOID'].includes(s))result.push('TERMINATE');return result})
function tabKey(event:KeyboardEvent){if(!['ArrowRight','ArrowLeft','Home','End'].includes(event.key))return;event.preventDefault();const buttons=Array.from((event.currentTarget as HTMLElement).querySelectorAll<HTMLButtonElement>('[role=tab]'));const i=developmentTabs.findIndex(t=>t.key===tab.value);const next=event.key==='Home'?0:event.key==='End'?buttons.length-1:(i+(event.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;tab.value=developmentTabs[next]!.key;buttons[next]?.focus()}
const label=(a:string)=>developmentActionLabel(a,workspace.value)||actionNames[a]||a
const fields=(section:Section)=>effective((section.fields??[]).filter(f=>!['changeReason','productId'].includes(f.key))).map(f=>({...f,label:({name:'项目名称',reason:'立项理由',owner:'开发负责人'} as Record<string,string>)[f.key]??f.label}))
function effective(list:Field[],source:Document=doc.value){return list.map(f=>{const key=({needId:'needs',selectedQuote:'quotes',quoteId:'quotes',selectedSample:'samples',previousId:'samples'} as Record<string,string>)[f.key];return key?{...f,type:'select' as const,options:rows(source,key).map(r=>[String(r.id),String(r.name||r.supplier||r.pain||r.id)])}:f})}
function columns(section:Section,source:Document=doc.value){return effective(section.columns??[],source)}
function tableColumns(section:Section){const keys:Record<string,string[]>={risk:['type','scope','investigator','date','conclusion'],requirements:['needId','proposal','priority','owner','result','testedVersion'],needs:['name','pain','nature'],quotes:['supplier','amount','currency','moq','leadTime','validUntil','specVersion'],samples:['name','specVersion','receivedDate','tester','result'],skus:['name','sampleId']};return columns(section).filter(f=>!keys[section.key]||keys[section.key]!.includes(f.key))}
const groupedChecks=computed(()=>developmentTabs.map(t=>({...t,issues:(readiness.value?.issues??[]).filter(issue=>developmentIssueTab(issue)===t.key)})).filter(t=>t.issues.length))
const changes=computed(()=>workspace.value?changedKeys(workspace.value.document,workspace.value.proposal):[])
function keyLabel(key:string){return sections.flatMap(s=>s.fields??[]).find(f=>f.key===key)?.label??sections.find(s=>s.rows===key)?.title??({changeReason:'变更原因',acceptedChange:'变更批准时间'} as Record<string,string>)[key]??key}
function showValue(document:Document,key:string){const value=document[key];if(Array.isArray(value)){const section=sections.find(s=>s.rows===key);return value.map((row,index)=>`${index+1}. `+(section?columns(section,document).map(f=>`${f.label}：${display(f,row[f.key])}`).join('；'):Object.values(row).join(' · '))).join('\n')}const field=effective(sections.flatMap(s=>s.fields??[]),document).find(f=>f.key===key);return field?display(field,value):String(value??'—')}
async function readReadiness(){const n=++readRequest;readinessError.value='';readiness.value=undefined;try{const result=await developmentWorkbenchApi.readiness(props.projectId);if(alive&&n===readRequest)readiness.value=result}catch(e){if(alive&&n===readRequest)readinessError.value=message(e)}}
function display(field:Field,value:unknown){if(value==null||value==='')return '—';if(['commission','advertising','loss'].includes(field.key))return `${Number(value)*100}%`;return field.options?.find(o=>o[0]===String(value))?.[1]??String(value)}
function accept(w:Workspace){workspace.value=w;void readReadiness();emit('changed')}
async function load(){loading.value=true;error.value='';try{const result=await api.get(props.projectId);legacy.value=result.legacy;if('version'in result.workspace){workspace.value=result.workspace as Workspace;void readReadiness()}else workspace.value=undefined}catch(e){error.value=message(e)}finally{loading.value=false}}
const message=(e:unknown)=>e instanceof Error?e.message:'操作失败，请重试'
async function initialize(){busy.value=true;try{accept(await api.initialize(props.projectId))}catch(e){error.value=message(e)}finally{busy.value=false}}
function edit(section:Section,row?:Row,basic=false){editError.value='';changeReason.value='';const isRows=!!section.rows&&!basic;editor.value={title:`${row?'编辑':isRows?'新增':'编辑'}${section.title}`,fields:(isRows?columns(section):fields(section)).filter(f=>!(f.key==='asin'&&sourceCandidate.value)&&f.key!=='skuId'&&!(f.key==='specVersion'&&workspace.value?.state==='ACTIVE'&&!isRows)),key:isRows?section.rows:undefined,id:row?.id};draft.value=isRows?{id:crypto.randomUUID(),...(section.key==='quotes'?{currency:'USD',specVersion:String(doc.value.specVersion??'1')}:section.key==='samples'?{specVersion:String(doc.value.specVersion??'1'),quoteId:String(doc.value.selectedQuote??''),result:'PENDING'}:section.key==='requirements'?{priority:'MUST',result:'PENDING'}:section.key==='cost'?{currency:'USD',rate:1}:{}),...row}:Object.fromEntries(fields(section).map(f=>[f.key,doc.value[f.key] as Value??'']));initial.value=JSON.stringify(draft.value)}
async function closeEditor(){if(!busy.value&&(!dirty.value||await confirmAction('放弃未保存的修改？')))editor.value=undefined}
async function saveEditor(){if(!editor.value||!workspace.value)return;busy.value=true;editError.value='';try{const next=structuredClone(JSON.parse(JSON.stringify(workspace.value.document))) as Document,edit=editor.value;if(edit.key){const list=rows(doc.value,edit.key);next[edit.key]=edit.remove?list.filter(r=>r.id!==edit.id):edit.id?list.map(r=>r.id===edit.id?{...r,...draft.value}:r):[...list,{...draft.value}]}else {const original=JSON.parse(initial.value) as Row;for(const [key,value] of Object.entries(draft.value))if(value!==original[key])next[key]=value;}next.changeReason=changeReason.value;accept(await api.save(props.projectId,workspace.value.version,next));editor.value=undefined;notice.value=Object.keys(workspace.value?.proposal??{}).length?'方案变更已提交，批准前仍执行原方案。':'资料已保存'}catch(e){editError.value=message(e)}finally{busy.value=false}}
function canRemove(section:Section){return !['samples','quotes','skus'].includes(section.key)}
async function remove(section:Section,row:Row){if(!workspace.value||!section.rows)return;if(section.rows==='needs'&&rows(doc.value,'requirements').some(r=>r.needId===row.id)){error.value='该需求已关联开发要求，请先调整关联。';return}if(!await confirmAction('移除此条明细？历史版本仍保留。'))return;editError.value='';changeReason.value='';editor.value={title:'移除'+section.title,fields:[],key:section.rows,id:row.id,remove:true};draft.value={...row};initial.value='__remove__'}
function ask(value:string){error.value='';editError.value='';action.value=value;reason.value='';selfConfirmed.value=false}
async function runAction(){if(!workspace.value)return;busy.value=true;editError.value='';try{accept(await api.action(props.projectId,workspace.value.version,action.value,reason.value,selfConfirmed.value));action.value='';notice.value='操作已完成'}catch(e){editError.value=message(e);void readReadiness()}finally{busy.value=false}}
async function findProducts(){productLoading.value=true;productError.value='';try{products.value=(await domainApi.products()).items.filter(p=>p.status==='ACTIVE'&&`${p.productName} ${p.productCode}`.toLowerCase().includes(productQuery.value.toLowerCase()))}catch(e){productError.value=message(e)}finally{productLoading.value=false}}
function openProduct(){productOpen.value=true;selectedProduct.value=undefined;selectedSkus.value=[];productQuery.value='';productError.value='';productInitial.value=JSON.stringify([undefined,[]]);void findProducts()}
function chooseProduct(product:ProductDetailDto){selectedProduct.value=product;selectedSkus.value=product.id===doc.value.productId?rows(doc.value,'skus').map(r=>String(r.skuId)).filter(id=>product.variants.some(v=>v.id===id&&v.status==='ACTIVE')):[]}
async function closeProduct(){if(!busy.value&&(!productDirty.value||await confirmAction('放弃未保存的商品与 SKU 选择？')))productOpen.value=false}
async function saveProduct(){if(!workspace.value||!selectedProduct.value||!selectedSkus.value.length)return;busy.value=true;productError.value='';try{const product=selectedProduct.value;const skus:Row[]=product.variants.filter(v=>v.id&&selectedSkus.value.includes(v.id)&&v.status==='ACTIVE').map(v=>rows(doc.value,'skus').find(r=>r.skuId===v.id)??{id:crypto.randomUUID(),skuId:v.id!,name:v.skuCode+' · '+v.variantName,sampleId:''});accept(await api.save(props.projectId,workspace.value.version,{...workspace.value.document,productId:product.id,productName:product.productName,productCode:product.productCode,skus}));productOpen.value=false;notice.value='商品与目标 SKU 已保存'}catch(e){productError.value=message(e)}finally{busy.value=false}}
async function files(){try{attachments.value=await attachmentList('DEVELOPMENT',props.projectId)}catch(e){error.value=message(e)}}
async function upload(file:File){if(busy.value)return false;busy.value=true;try{await uploadAttachment('DEVELOPMENT',props.projectId,file);await files();notice.value='附件已上传，可在开发或验收依据中引用附件名称。'}catch(e){error.value=message(e); return false }finally{busy.value=false}}
async function download(file:LaunchAttachment){try{await downloadAttachment('DEVELOPMENT',props.projectId,file)}catch(e){error.value=message(e)}}
async function guard(){return !busy.value&&(!dirty.value||await confirmAction('放弃未保存的项目修改？'))}
async function close(){if(await guard())emit('close')}
function unload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
onBeforeRouteLeave(guard);onBeforeRouteUpdate(guard)
watch(tab,v=>{if(v==='handover')void files()})
onMounted(()=>{previous=document.activeElement as HTMLElement;dialog.value?.showModal();void load();window.addEventListener('beforeunload',unload)})
onBeforeUnmount(()=>{alive=false;window.removeEventListener('beforeunload',unload);dialog.value?.close();previous?.focus({preventScroll:true})})
</script>
<template>
  <!-- eslint-disable vue/max-attributes-per-line, vue/singleline-html-element-content-newline -->
  <dialog ref="dialog" class="candidate-detail candidate-ui development-ui" aria-label="新品开发详情" @cancel.prevent="close">
    <header class="candidate-detail-header"><div><h2>{{ doc.name||'新品开发项目' }}</h2><small>方案版本 {{ doc.specVersion||'—' }} <span class="candidate-badge" :data-state="workspace?.state">{{ stateNames[workspace?.state??''] }}</span><RouterLink v-if="sourceCandidate&&session.canAccess(['selection.read'])" :to="`/selection/candidates/${sourceCandidate}`">来源候选 ↗</RouterLink></small></div><button aria-label="关闭详情" :disabled="busy" @click="close">×</button></header>
    <nav class="candidate-detail-tabs" role="tablist" aria-label="项目内容" @keydown="tabKey"><button v-for="t in developmentTabs" :id="`development-tab-${t.key}`" :key="t.key" role="tab" :aria-selected="tab===t.key" :tabindex="tab===t.key?0:-1" :aria-controls="`development-panel-${t.key}`" :aria-current="tab===t.key?'page':undefined" @click="tab=t.key">{{ t.title }}<i v-if="t.key==='changes'&&Object.keys(workspace?.proposal??{}).length" class="development-dot" /></button></nav>
    <main :id="`development-panel-${tab}`" class="candidate-detail-body" role="tabpanel" :aria-labelledby="`development-tab-${tab}`">
      <p v-if="error" role="alert" class="data-state--error">{{ error }} <button v-if="!workspace" @click="load">重试</button></p><SuccessToast :message="notice" />
      <p v-if="loading">正在加载项目资料…</p><div v-else-if="!workspace" class="data-state"><h3>启用分阶段开发工作台</h3><p>保留原项目资料与状态，逐步补充方案、供应、打样和交接信息。</p><button v-if="writer" :disabled="busy" class="candidate-primary" @click="initialize">启用开发工作台</button></div>
      <template v-else>
        <div v-if="Object.keys(workspace.proposal).length" class="development-change-alert"><span>方案变更待审核，当前仍执行已批准方案。</span><button @click="tab='changes'">查看变更对比</button></div>
        <details v-if="readiness?.issues.some(i=>developmentIssueTab(i)===tab)" class="candidate-issues"><summary>本模块待办（{{ readiness.issues.filter(i=>developmentIssueTab(i)===tab).length }}）</summary><ul><li v-for="(issue,index) in readiness.issues.filter(i=>developmentIssueTab(i)===tab)" :key="index">{{ issue }}</li></ul></details>
        <template v-if="tab==='overview'">
          <section class="candidate-section"><div class="candidate-section-heading"><h3>开发进度</h3><span v-if="overdue(doc,workspace.state)" class="development-warning">计划已逾期，请核对进度</span><button v-if="Object.keys(workspace.baseline).length" @click="snapshot=workspace.baseline">查看立项基线</button></div><ol class="development-stages"><li v-for="(name,index) in stages" :key="index" :class="{done:workspace.state==='COMPLETED'||index<workspace.stage,current:workspace.state!=='COMPLETED'&&index===workspace.stage}"><button @click="tab=stageGuides[index]!.tab"><b>{{ workspace.state==='COMPLETED'||index<workspace.stage?'✓':index+1 }}</b><span>{{ name }}</span></button></li></ol><p class="candidate-hint">{{ workspace.state==='DRAFT'?(Object.keys(workspace.baseline).length?'候选已通过评估。确认负责人和计划起止日期后，接手开始开发。':'独立项目需补齐立项资料，审核通过后接手开发。'):workspace.state==='COMPLETED'?'项目已完成，定型资料和操作历史只读保留。':workspace.state==='PAUSED'?'项目已暂停，恢复后继续当前阶段。':stageGuides[workspace.stage]?.text }}</p></section>
          <div class="candidate-metrics"><article><span>开发负责人</span><strong>{{ doc.owner||'待分配' }}</strong></article><article><span>计划完成日</span><strong>{{ doc.endDate||'待安排' }}</strong></article><article><span>打样轮次</span><strong>{{ rows(doc,'samples').length }}<small> 轮</small></strong></article><article><span>单件贡献 · USD</span><strong>{{ workspace.calculation?.profit?.toFixed(2)??'待试算' }}</strong></article></div>
          <section v-if="!['COMPLETED','VOID','PAUSED'].includes(workspace.state)" class="candidate-checklist"><div class="candidate-section-heading"><h3>下一步：{{ Object.keys(workspace.proposal).length?'处理方案变更':readiness?.action?label(readiness.action):'核对阶段资料' }}</h3><button :disabled="busy" @click="readReadiness">检查待办</button></div><p v-if="readinessError" role="alert">{{ readinessError }}</p><p v-else-if="!readiness">正在检查阶段要求…</p><template v-else><div v-if="readiness.issues.length" class="candidate-check-grid"><button v-for="group in groupedChecks" :key="group.key" @click="tab=group.key"><b>{{ group.title }} <span>{{ group.issues.length }}</span></b><small>{{ group.issues[0] }}</small></button></div><p v-else>当前阶段检查已通过，操作时仍会重新校验最新资料。</p><p class="candidate-hint">阶段检查按顺序提示；补充后再次检查。方案变更、报价有效期与验证版本均会影响推进。</p></template><div class="development-shortcuts"><button @click="tab='scheme'">完善方案与要求</button><button @click="tab='supply'">维护报价与样品</button><button @click="tab='risk'">完成风险复核</button><button @click="tab='handover'">关联商品与交接</button></div></section>
        </template>
        <section v-if="tab==='cost'" class="candidate-metrics"><article v-for="(name,key) in {unitCost:'单位成本 USD',profit:'单件贡献 USD',margin:'贡献率',breakEven:'盈亏平衡售价 USD'}" :key="key"><span>{{ name }}</span><strong>{{ workspace.calculation?.[key]!=null?(key==='margin'?(Number(workspace.calculation[key])*100).toFixed(1)+'%':Number(workspace.calculation[key]).toFixed(2)):'待完善' }}</strong></article></section>
        <section v-if="tab==='risk'" class="candidate-checklist"><div class="candidate-section-heading"><h3>{{ workspace.riskReview.valid?'风险调查已复核':'风险调查待复核' }}</h3><button v-if="editable&&reviewer" :disabled="busy" @click="ask('REVIEW_RISK')">复核风险调查</button></div><p>当前方案版本：{{ doc.specVersion }}；已调查版本：{{ doc.riskVersion||'未填写' }}。方案变更后须重新调查和复核。</p><p v-if="workspace.riskReview.actor">{{ workspace.riskReview.actor }} · {{ formatDate(workspace.riskReview.date) }} · {{ workspace.riskReview.reason }}</p></section>
        <section v-if="tab==='handover'" class="candidate-section"><div class="candidate-section-heading"><h3>关联商品与目标 SKU</h3><button v-if="editable&&session.canAccess(['products.read'])" :disabled="busy" @click="openProduct">选择商品与 SKU</button></div><p>{{ doc.productName||doc.productId||'尚未关联自有商品' }} <small>{{ doc.productCode }}</small></p><p class="candidate-hint">仅勾选本项目涉及的启用 SKU，不自动带入父体全部 SKU。已保存的样品覆盖说明会保留。</p><RouterLink v-if="doc.productId&&session.canAccess(['products.read'])" :to="`/products/${doc.productId}`">查看关联商品 ↗</RouterLink></section>
        <section v-for="section in currentSections" :key="section.key" class="candidate-section"><div class="candidate-section-heading"><h3>{{ section.key==='overview'?'项目基本信息':section.title }}</h3><div v-if="editable"><button v-if="fields(section).length" :disabled="busy" @click="edit(section,undefined,true)">编辑资料</button><button v-if="section.rows&&section.key!=='skus'" :disabled="busy" @click="edit(section)">{{ section.key==='samples'?'＋ 新增打样轮次':section.key==='quotes'?'＋ 新增报价':'＋ 新增明细' }}</button></div></div><p class="candidate-hint">{{ section.key==='overview'?'明确项目责任、协作人员与计划日期，保留目标客户和立项依据。':section.description }}</p><dl v-if="fields(section).length" class="candidate-facts"><div v-for="field in fields(section)" :key="field.key" :class="{'candidate-field-wide':field.type==='textarea'}"><dt>{{ field.label.replace('（0–1）','（%）') }}</dt><dd><a v-if="['sourceUrl','imageUrl'].includes(field.key)&&safeLink(doc[field.key])" :href="safeLink(doc[field.key])" target="_blank" rel="noopener noreferrer">查看链接 ↗</a><template v-else>{{ display(field,doc[field.key]) }}</template></dd></div></dl><div v-if="section.rows" class="candidate-row-table"><table><thead><tr><th v-for="field in tableColumns(section)" :key="field.key">{{ field.label }}</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows(doc,section.rows)" :key="String(row.id)"><td v-for="field in tableColumns(section)" :key="field.key">{{ field.key==='type'?riskNames[String(row[field.key])]??row[field.key]:field.key==='conclusion'?riskLabels[String(row[field.key])]??row[field.key]:display(field,row[field.key]) }}<small v-if="field.key==='supplier'&&doc.selectedQuote===row.id" class="development-selected">已选定</small><small v-if="field.key==='name'&&section.key==='samples'&&doc.selectedSample===row.id" class="development-selected">最终样品</small></td><td><button :disabled="busy" @click="edit(section,row)">{{ editable?'编辑':'查看' }}</button><button v-if="editable&&canRemove(section)" :disabled="busy" @click="remove(section,row)">移除</button></td></tr><tr v-if="!rows(doc,section.rows).length"><td :colspan="tableColumns(section).length+1" class="data-state">暂无明细{{ editable?'，请补充本阶段资料。':'。' }}</td></tr></tbody></table></div></section>
        <section v-if="tab==='handover'" class="candidate-section"><div class="candidate-section-heading"><h3>附件资料</h3></div><SingleFileUpload v-if="editable" title="开发附件" accept=".pdf,.png,.jpg,.jpeg" :max-mb="5" :disabled="busy" :upload="upload" /><p v-if="!attachments.length" class="candidate-hint">暂无附件，可上传报价、样品验收报告、调查材料与交接文件。</p><div v-for="file in attachments" :key="file.id" class="candidate-file"><button @click="download(file)">{{ file.name }}</button><small>{{ Math.ceil(file.size/1024) }} KB</small></div></section>
        <section v-if="tab==='changes'" class="candidate-section"><div class="candidate-section-heading"><h3>方案变更</h3><button v-if="Object.keys(workspace.baseline).length" @click="snapshot=workspace.baseline">查看立项基线</button></div><p class="candidate-hint">开发中修改关键规格、需求、成本、计划完成日或选定供应方案，会提交变更审批。批准后更新方案版本并回到方案确认阶段，原样品和风险结论需重新核对。</p><template v-if="Object.keys(workspace.proposal).length"><p>变更原因：{{ workspace.proposal.changeReason||'—' }}</p><div class="candidate-row-table"><table class="development-diff"><thead><tr><th>变更项目</th><th>当前执行方案</th><th>待批准方案</th></tr></thead><tbody><tr v-for="key in changes" :key="key"><td>{{ keyLabel(key) }}</td><td>{{ showValue(workspace.document,key) }}</td><td>{{ showValue(workspace.proposal,key) }}</td></tr></tbody></table></div><div v-if="writer&&reviewer&&workspace.state==='ACTIVE'" class="development-shortcuts"><button class="candidate-primary" @click="ask('CHANGE_APPROVE')">批准变更</button><button @click="ask('CHANGE_REJECT')">驳回变更</button></div></template><p v-else>暂无待审核变更。已处理的变更可在操作记录中查看。</p></section>
        <section v-if="tab==='history'" class="candidate-section"><h3>操作记录 <small>{{ history.length }} 条</small></h3><div v-for="entry in historyRows" :key="entry.version" class="candidate-history"><div><b>{{ entry.action==='SUBMIT'?(entry.snapshot.state==='FINAL_REVIEW'?'提交完成审核':'提交立项审核'):label(entry.action) }}</b><span>{{ entry.actor }} · {{ formatDate(entry.date) }} · 版本 {{ entry.version }}</span></div><p>{{ entry.reason||'—' }}</p><small>{{ stateNames[entry.snapshot.state] }} · {{ stages[entry.snapshot.stage??0] }}</small> <button @click="snapshot=entry.snapshot.document">查看版本资料</button></div><p v-if="!history.length">暂无操作记录</p></section>
      </template>
    </main>
    <footer class="candidate-detail-footer"><ListPagination v-if="tab==='history'" :page="historyPage" :page-size="historySize" :total="history.length" @update:page="historyPage=$event" @update:page-size="historySize=$event;historyPage=1" /><template v-else><span>{{ editable?'按模块保存资料，完成要求后推进阶段。':'当前资料只读，历史与审批记录保留。' }}</span><div><button v-for="(a,index) in actions" :key="a" :class="{'candidate-primary':index===0&&!['TERMINATE','PAUSE','WITHDRAW'].includes(a),'development-danger':a==='TERMINATE'}" :disabled="busy" @click="ask(a)">{{ label(a) }}</button></div></template></footer>
  </dialog>
  <AccessDialog v-if="editor" :title="editor.title" :busy="busy" :dirty="dirty" wide @close="editor=undefined"><form id="development-edit" @submit.prevent="saveEditor"><p v-if="editError" role="alert" class="data-state--error">{{ editError }}</p><p v-if="editor.remove">确认移除此条明细。已有历史记录仍可追溯。</p><CandidateFields :fields="editor.fields" :model="draft" :disabled="!editable||busy" @change="(key,value)=>draft[key]=value" /><label v-if="editable&&workspace?.state==='ACTIVE'" class="development-change-reason">变更原因<textarea v-model.trim="changeReason" maxlength="2000" rows="2" placeholder="修改关键方案、成本或计划时必填；普通进度和验收记录可不填。" /></label></form><template #footer><button :disabled="busy" @click="closeEditor">{{ editable?'取消':'关闭' }}</button><button v-if="editable" class="candidate-primary" form="development-edit" :disabled="busy||!dirty">{{ busy?'保存中…':editor.remove?'确认移除':'保存' }}</button></template></AccessDialog>
  <AccessDialog v-if="action" :title="label(action)" :busy="busy" @close="action=''"><form id="development-action" class="access-form" @submit.prevent="runAction"><p v-if="editError" role="alert" class="data-state--error">{{ editError }}</p><p v-if="action==='CHANGE_APPROVE'">批准后更新方案版本并返回方案确认阶段，样品与风险须重新核对。</p><p v-else-if="action==='NEXT'">完成当前阶段后进入“{{ stages[(workspace?.stage??0)+1] }}”，系统将校验方案、样品与风险资料。</p><p v-else-if="action==='TERMINATE'">终止后项目只读保留，请说明终止原因及后续处置。</p><p v-else-if="action==='COMPLETE'">通过后定型资料只读保存。开发完成不代表已采购或已上架。</p><label>操作说明<textarea v-model="reason" :required="!['START','SUBMIT','NEXT','WITHDRAW'].includes(action)" maxlength="2000" rows="3" /></label><label v-if="['APPROVE','COMPLETE','CHANGE_APPROVE'].includes(action)"><input v-model="selfConfirmed" type="checkbox">若本人提交，确认执行自审并保留审计记录</label></form><template #footer><button :disabled="busy" @click="action=''">取消</button><button class="candidate-primary" form="development-action" :disabled="busy">{{ busy?'处理中…':'确认'+label(action) }}</button></template></AccessDialog>
  <AccessDialog v-if="snapshot" title="版本资料（只读）" wide @close="snapshot=undefined"><section v-for="section in sections" :key="section.key" class="candidate-section"><h3>{{ section.title }}</h3><dl class="candidate-facts"><div v-for="field in effective(section.fields??[],snapshot)" :key="field.key"><dt>{{ field.label }}</dt><dd>{{ display(field,snapshot[field.key]) }}</dd></div></dl><div v-if="section.rows"><dl v-for="(row,index) in rows(snapshot,section.rows)" :key="index" class="candidate-facts"><div v-for="field in columns(section,snapshot)" :key="field.key"><dt>{{ field.label }}</dt><dd>{{ display(field,row[field.key]) }}</dd></div></dl></div></section></AccessDialog>
  <AccessDialog v-if="productOpen" title="选择商品与目标 SKU" :busy="busy" :dirty="productDirty" wide @close="productOpen=false"><p v-if="productError" role="alert" class="data-state--error">{{ productError }}</p><form class="development-product-search" @submit.prevent="findProducts"><label>商品搜索<input v-model="productQuery" placeholder="商品名称 / 编码"></label><button :disabled="productLoading">搜索</button></form><div class="development-product-picker"><section><p v-if="productLoading">正在加载商品…</p><button v-for="p in products" :key="p.id" :disabled="busy" :aria-pressed="selectedProduct?.id===p.id" @click="chooseProduct(p)">{{ p.productName }}<small>{{ p.productCode }}</small></button><p v-if="!products.length&&!productLoading">没有找到启用商品</p></section><section><p v-if="!selectedProduct">先选择商品，再勾选本次开发的 SKU。</p><template v-else><h3>{{ selectedProduct.productName }}</h3><label v-for="variant in selectedProduct.variants.filter(v=>v.status==='ACTIVE'&&v.id)" :key="variant.id"><input v-model="selectedSkus" :disabled="busy" type="checkbox" :value="variant.id">{{ variant.skuCode }} · {{ variant.variantName }}</label><p v-if="!selectedProduct.variants.some(v=>v.status==='ACTIVE'&&v.id)">此商品没有启用的 SKU</p></template></section></div><template #footer><span>已选 {{ selectedSkus.length }} 个 SKU</span><button :disabled="busy" @click="closeProduct">取消</button><button class="candidate-primary" :disabled="busy||!selectedProduct||!selectedSkus.length" @click="saveProduct">{{ busy?'保存中…':'保存关联' }}</button></template></AccessDialog>
</template>
